      "react": "\"use client\";\n\nimport { useRef } from \"react\";\nimport gsap from \"gsap\";\nimport { ScrollTrigger } from \"gsap/ScrollTrigger\";\nimport { useGSAP } from \"@gsap/react\";\n\ngsap.registerPlugin(useGSAP, ScrollTrigger);\n\nconst HIDDEN = {\n  up: \"inset(100% 0% 0% 0%)\",\n  down: \"inset(0% 0% 100% 0%)\",\n  left: \"inset(0% 0% 0% 100%)\",\n  right: \"inset(0% 100% 0% 0%)\",\n} as const;\n\nexport type ImageRevealProps = {\n  /** The image (or any media) to uncover. */\n  children: React.ReactNode;\n  /** Seconds the mask takes to open. */\n  duration?: number;\n  /** Which way the mask opens: \"up\" uncovers from the bottom edge upwards. */\n  direction?: keyof typeof HIDDEN;\n  /** How far the image is zoomed in before it settles, 1 for no zoom. */\n  zoom?: number;\n  /** A GSAP ease name, e.g. \"expo.inOut\". */\n  ease?: string;\n  /** Where the top of the image must reach in the viewport before it reveals. */\n  start?: string;\n  /**\n   * The element that scrolls, if it isn't the page. Pass the element itself (from a\n   * callback ref or useState). While it is `null` nothing is set up; leave it out to\n   * use the page.\n   */\n  scroller?: HTMLElement | null;\n  className?: string;\n};\n\n/**\n * Uncovers an image with a sliding mask as it scrolls into view, while the image\n * settles from a slight zoom.\n *\n * Plays once. Under `prefers-reduced-motion: reduce` the image fades in instead.\n */\nexport function ImageReveal({\n  children,\n  duration = 1.2,\n  direction = \"up\",\n  zoom = 1.25,\n  ease = \"expo.inOut\",\n  start = \"top 85%\",\n  scroller,\n  className,\n}: ImageRevealProps) {\n  const scope = useRef<HTMLDivElement>(null);\n  const media = useRef<HTMLDivElement>(null);\n\n  useGSAP(\n    () => {\n      // A scroller was asked for but isn't mounted yet: wait for it.\n      if (scroller === null) return;\n      const frame = scope.current;\n      const inner = media.current;\n      if (!frame || !inner) return;\n\n      gsap.matchMedia().add(\n        {\n          motion: \"(prefers-reduced-motion: no-preference)\",\n          reduced: \"(prefers-reduced-motion: reduce)\",\n        },\n        (context) => {\n          const reduced = context.conditions?.reduced ?? false;\n          const scrollTrigger = {\n            trigger: frame,\n            scroller: scroller ?? undefined,\n            start,\n            once: true,\n          };\n          if (reduced) {\n            gsap.from(frame, { opacity: 0, duration: 0.3, clearProps: \"opacity\", scrollTrigger });\n            return;\n          }\n          // clip-path, not transform: the frame keeps its size while its visible area grows.\n          gsap\n            .timeline({ scrollTrigger })\n            .fromTo(\n              frame,\n              { clipPath: HIDDEN[direction] },\n              { clipPath: \"inset(0% 0% 0% 0%)\", duration, ease },\n            )\n            .from(inner, { scale: zoom, duration: duration * 1.2, ease: \"power2.out\" }, 0);\n        },\n        scope,\n      );\n    },\n    {\n      scope,\n      dependencies: [duration, direction, zoom, ease, start, scroller],\n      revertOnUpdate: true,\n    },\n  );\n\n  return (\n    <div ref={scope} data-slot=\"image-reveal\" className={className} style={{ overflow: \"hidden\" }}>\n      <div ref={media} data-slot=\"image-reveal-media\" style={{ width: \"100%\", height: \"100%\" }}>\n        {children}\n      </div>\n    </div>\n  );\n}\n",
      "vue": "<script setup lang=\"ts\">\n/**\n * Uncovers an image with a sliding mask as it scrolls into view, while the image\n * settles from a slight zoom. Plays once. Under `prefers-reduced-motion: reduce`\n * the image fades in instead.\n */\nimport { onMounted, onUnmounted, ref, watch } from \"vue\";\nimport gsap from \"gsap\";\nimport { ScrollTrigger } from \"gsap/ScrollTrigger\";\n\ngsap.registerPlugin(ScrollTrigger);\n\nconst HIDDEN = {\n  up: \"inset(100% 0% 0% 0%)\",\n  down: \"inset(0% 0% 100% 0%)\",\n  left: \"inset(0% 0% 0% 100%)\",\n  right: \"inset(0% 100% 0% 0%)\",\n} as const;\n\nconst props = withDefaults(\n  defineProps<{\n    duration?: number;\n    direction?: keyof typeof HIDDEN;\n    zoom?: number;\n    ease?: string;\n    start?: string;\n    scroller?: HTMLElement | null;\n  }>(),\n  { duration: 1.2, direction: \"up\", zoom: 1.25, ease: \"expo.inOut\", start: \"top 85%\" }\n);\n\nconst frame = ref<HTMLElement | null>(null);\nconst media = ref<HTMLElement | null>(null);\nlet ctx: gsap.Context | undefined;\n\nconst setup = () => {\n  ctx?.revert();\n  // A scroller was asked for but isn't mounted yet: wait for it.\n  if (props.scroller === null) return;\n  const f = frame.value;\n  const m = media.value;\n  if (!f || !m) return;\n  ctx = gsap.context(() => {\n    gsap.matchMedia().add(\n      {\n        motion: \"(prefers-reduced-motion: no-preference)\",\n        reduced: \"(prefers-reduced-motion: reduce)\",\n      },\n      (context) => {\n        const scrollTrigger = { trigger: f, scroller: props.scroller ?? undefined, start: props.start, once: true };\n        if (context.conditions?.reduced) {\n          gsap.from(f, { opacity: 0, duration: 0.3, clearProps: \"opacity\", scrollTrigger });\n          return;\n        }\n        gsap\n          .timeline({ scrollTrigger })\n          .fromTo(\n            f,\n            { clipPath: HIDDEN[props.direction] },\n            { clipPath: \"inset(0% 0% 0% 0%)\", duration: props.duration, ease: props.ease }\n          )\n          .from(m, { scale: props.zoom, duration: props.duration * 1.2, ease: \"power2.out\" }, 0);\n      }\n    );\n  }, f);\n};\n\nonMounted(setup);\nwatch(() => ({ ...props }), setup, { deep: true });\nonUnmounted(() => ctx?.revert());\n</script>\n\n<template>\n  <div ref=\"frame\" data-slot=\"image-reveal\" style=\"overflow: hidden\">\n    <div ref=\"media\" data-slot=\"image-reveal-media\" style=\"width: 100%; height: 100%\">\n      <slot />\n    </div>\n  </div>\n</template>\n",
      "html": "<!--\n  Image Reveal Mask — uncovers an image with a sliding mask as it scrolls into view,\n  while the image settles from a slight zoom. Plays once.\n  Under prefers-reduced-motion: reduce the image fades in instead.\n-->\n<div data-slot=\"image-reveal\" id=\"image-reveal\" style=\"overflow: hidden; aspect-ratio: 3 / 2\">\n  <div data-slot=\"image-reveal-media\" style=\"width: 100%; height: 100%\">\n    <img src=\"/roastery.avif\" alt=\"The roastery in Yaba\" style=\"width: 100%; height: 100%; object-fit: cover\" />\n  </div>\n</div>\n\n<script type=\"module\">\n  import gsap from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/index.js\";\n  import { ScrollTrigger } from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/ScrollTrigger.js\";\n\n  gsap.registerPlugin(ScrollTrigger);\n\n  const HIDDEN = {\n    up: \"inset(100% 0% 0% 0%)\",\n    down: \"inset(0% 0% 100% 0%)\",\n    left: \"inset(0% 0% 0% 100%)\",\n    right: \"inset(0% 100% 0% 0%)\",\n  };\n  const frame = document.querySelector(\"#image-reveal\");\n  const media = frame.querySelector(\"[data-slot='image-reveal-media']\");\n  const options = { duration: 1.2, direction: \"up\", zoom: 1.25, ease: \"expo.inOut\", start: \"top 85%\" };\n\n  gsap.matchMedia().add(\n    {\n      motion: \"(prefers-reduced-motion: no-preference)\",\n      reduced: \"(prefers-reduced-motion: reduce)\",\n    },\n    (context) => {\n      const scrollTrigger = { trigger: frame, start: options.start, once: true };\n      if (context.conditions.reduced) {\n        gsap.from(frame, { opacity: 0, duration: 0.3, clearProps: \"opacity\", scrollTrigger });\n        return;\n      }\n      gsap\n        .timeline({ scrollTrigger })\n        .fromTo(\n          frame,\n          { clipPath: HIDDEN[options.direction] },\n          { clipPath: \"inset(0% 0% 0% 0%)\", duration: options.duration, ease: options.ease }\n        )\n        .from(media, { scale: options.zoom, duration: options.duration * 1.2, ease: \"power2.out\" }, 0);\n    }\n  );\n</script>\n"
