      "react": "\"use client\";\n\nimport { useRef } from \"react\";\nimport gsap from \"gsap\";\nimport { useGSAP } from \"@gsap/react\";\n\ngsap.registerPlugin(useGSAP);\n\nexport type MagneticButtonProps = React.ComponentPropsWithoutRef<\"button\"> & {\n  /** How far the button follows the pointer, as a share of the pointer's offset (0–1). */\n  strength?: number;\n  /** How much further the label travels than the button, for a sense of depth. */\n  depth?: number;\n  /** Seconds the button takes to spring home when the pointer leaves. */\n  duration?: number;\n  /** The ease of the return, e.g. \"elastic.out(1, 0.4)\". */\n  ease?: string;\n};\n\n/**\n * A button that leans toward the pointer while it hovers, then springs back when it leaves.\n *\n * Only runs where there is a precise hovering pointer, so on a phone it is a normal\n * button. Under `prefers-reduced-motion: reduce` it never moves.\n */\nexport function MagneticButton({\n  children,\n  strength = 0.35,\n  depth = 0.5,\n  duration = 0.9,\n  ease = \"elastic.out(1, 0.4)\",\n  className,\n  ...rest\n}: MagneticButtonProps) {\n  const scope = useRef<HTMLButtonElement>(null);\n\n  useGSAP(\n    () => {\n      const button = scope.current;\n      const label = button?.querySelector<HTMLElement>(\"[data-slot='magnetic-button-label']\");\n      if (!button || !label) return;\n\n      gsap.matchMedia().add(\n        \"(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)\",\n        () => {\n          const follow = { duration: 0.4, ease: \"power3.out\" };\n          const bx = gsap.quickTo(button, \"x\", follow);\n          const by = gsap.quickTo(button, \"y\", follow);\n          const lx = gsap.quickTo(label, \"x\", follow);\n          const ly = gsap.quickTo(label, \"y\", follow);\n\n          const move = (event: PointerEvent) => {\n            const box = button.getBoundingClientRect();\n            const dx = event.clientX - (box.left + box.width / 2);\n            const dy = event.clientY - (box.top + box.height / 2);\n            bx(dx * strength);\n            by(dy * strength);\n            lx(dx * strength * depth);\n            ly(dy * strength * depth);\n          };\n          const leave = () =>\n            gsap.to([button, label], { x: 0, y: 0, duration, ease, overwrite: true });\n\n          button.addEventListener(\"pointermove\", move);\n          button.addEventListener(\"pointerleave\", leave);\n          return () => {\n            button.removeEventListener(\"pointermove\", move);\n            button.removeEventListener(\"pointerleave\", leave);\n          };\n        },\n        scope,\n      );\n    },\n    { scope, dependencies: [strength, depth, duration, ease], revertOnUpdate: true },\n  );\n\n  return (\n    <button ref={scope} type=\"button\" data-slot=\"magnetic-button\" className={className} {...rest}>\n      <span data-slot=\"magnetic-button-label\" style={{ display: \"inline-block\" }}>\n        {children}\n      </span>\n    </button>\n  );\n}\n",
      "vue": "<script setup lang=\"ts\">\n/**\n * A button that leans toward the pointer while it hovers, then springs back when it leaves.\n * Only runs where there is a precise hovering pointer. Under `prefers-reduced-motion:\n * reduce` it never moves. Attributes and listeners fall through to the <button>.\n */\nimport { onMounted, onUnmounted, ref, watch } from \"vue\";\nimport gsap from \"gsap\";\n\nconst props = withDefaults(\n  defineProps<{ strength?: number; depth?: number; duration?: number; ease?: string }>(),\n  { strength: 0.35, depth: 0.5, duration: 0.9, ease: \"elastic.out(1, 0.4)\" }\n);\n\nconst button = ref<HTMLButtonElement | null>(null);\nconst label = ref<HTMLElement | null>(null);\nlet ctx: gsap.Context | undefined;\n\nconst setup = () => {\n  ctx?.revert();\n  const b = button.value;\n  const l = label.value;\n  if (!b || !l) return;\n  ctx = gsap.context(() => {\n    gsap.matchMedia().add(\n      \"(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)\",\n      () => {\n        const follow = { duration: 0.4, ease: \"power3.out\" };\n        const bx = gsap.quickTo(b, \"x\", follow);\n        const by = gsap.quickTo(b, \"y\", follow);\n        const lx = gsap.quickTo(l, \"x\", follow);\n        const ly = gsap.quickTo(l, \"y\", follow);\n        const move = (event: PointerEvent) => {\n          const box = b.getBoundingClientRect();\n          const dx = event.clientX - (box.left + box.width / 2);\n          const dy = event.clientY - (box.top + box.height / 2);\n          bx(dx * props.strength);\n          by(dy * props.strength);\n          lx(dx * props.strength * props.depth);\n          ly(dy * props.strength * props.depth);\n        };\n        const leave = () =>\n          gsap.to([b, l], { x: 0, y: 0, duration: props.duration, ease: props.ease, overwrite: true });\n        b.addEventListener(\"pointermove\", move);\n        b.addEventListener(\"pointerleave\", leave);\n        return () => {\n          b.removeEventListener(\"pointermove\", move);\n          b.removeEventListener(\"pointerleave\", leave);\n        };\n      }\n    );\n  }, b);\n};\n\nonMounted(setup);\nwatch(() => ({ ...props }), setup, { deep: true });\nonUnmounted(() => ctx?.revert());\n</script>\n\n<template>\n  <button ref=\"button\" type=\"button\" data-slot=\"magnetic-button\">\n    <span ref=\"label\" data-slot=\"magnetic-button-label\" style=\"display: inline-block\"><slot /></span>\n  </button>\n</template>\n",
      "html": "<!--\n  Magnetic Button — leans toward the pointer while it hovers, then springs back.\n  Only runs with a precise hovering pointer; never moves under prefers-reduced-motion.\n-->\n<button type=\"button\" data-slot=\"magnetic-button\" id=\"magnetic-button\">\n  <span data-slot=\"magnetic-button-label\" style=\"display: inline-block\">Order a bag</span>\n</button>\n\n<script type=\"module\">\n  import gsap from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/index.js\";\n\n  const button = document.querySelector(\"#magnetic-button\");\n  const label = button.querySelector(\"[data-slot='magnetic-button-label']\");\n  const options = { strength: 0.35, depth: 0.5, duration: 0.9, ease: \"elastic.out(1, 0.4)\" };\n\n  gsap.matchMedia().add(\n    \"(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)\",\n    () => {\n      const follow = { duration: 0.4, ease: \"power3.out\" };\n      const bx = gsap.quickTo(button, \"x\", follow);\n      const by = gsap.quickTo(button, \"y\", follow);\n      const lx = gsap.quickTo(label, \"x\", follow);\n      const ly = gsap.quickTo(label, \"y\", follow);\n      const move = (event) => {\n        const box = button.getBoundingClientRect();\n        const dx = event.clientX - (box.left + box.width / 2);\n        const dy = event.clientY - (box.top + box.height / 2);\n        bx(dx * options.strength);\n        by(dy * options.strength);\n        lx(dx * options.strength * options.depth);\n        ly(dy * options.strength * options.depth);\n      };\n      const leave = () =>\n        gsap.to([button, label], { x: 0, y: 0, duration: options.duration, ease: options.ease, overwrite: true });\n      button.addEventListener(\"pointermove\", move);\n      button.addEventListener(\"pointerleave\", leave);\n      return () => {\n        button.removeEventListener(\"pointermove\", move);\n        button.removeEventListener(\"pointerleave\", leave);\n      };\n    }\n  );\n</script>\n"
