      "react": "\"use client\";\n\nimport { useRef } from \"react\";\nimport gsap from \"gsap\";\nimport { useGSAP } from \"@gsap/react\";\n\ngsap.registerPlugin(useGSAP);\n\nexport type RiseInProps = {\n  /** The elements to reveal. Each direct child animates as one step. */\n  children: React.ReactNode;\n  /** Seconds each child takes to arrive. */\n  duration?: number;\n  /** How far below its resting place each child starts, in pixels. */\n  distance?: number;\n  /** Seconds between one child starting and the next. */\n  stagger?: number;\n  /** A GSAP ease name, e.g. \"expo.out\". */\n  ease?: string;\n  /** Seconds to wait before the first child moves. */\n  delay?: number;\n  /** Reveal children one after another, or all together. */\n  staggered?: boolean;\n  className?: string;\n};\n\n/**\n * Reveals a stack of elements by lifting them into place, one after another.\n *\n * Under `prefers-reduced-motion: reduce` the children cross-fade in place with\n * no travel and no stagger — the content still announces itself, nothing moves.\n */\nexport function RiseIn({\n  children,\n  duration = 0.9,\n  distance = 24,\n  stagger = 0.06,\n  ease = \"expo.out\",\n  delay = 0,\n  staggered = true,\n  className,\n}: RiseInProps) {\n  const scope = useRef<HTMLDivElement>(null);\n\n  useGSAP(\n    () => {\n      const items = gsap.utils.toArray<HTMLElement>(\"[data-slot='rise-in-item']\");\n      if (items.length === 0) return;\n\n      const mm = gsap.matchMedia();\n\n      mm.add(\n        {\n          motion: \"(prefers-reduced-motion: no-preference)\",\n          reduced: \"(prefers-reduced-motion: reduce)\",\n        },\n        (context) => {\n          const reduced = context.conditions?.reduced ?? false;\n          gsap.from(items, {\n            // Travel and stagger are the two things reduced motion drops.\n            y: reduced ? 0 : distance,\n            opacity: 0,\n            duration: reduced ? 0.2 : duration,\n            delay,\n            ease: reduced ? \"none\" : ease,\n            stagger: reduced || !staggered ? 0 : stagger,\n            // Leave the DOM exactly as authored once the reveal is done.\n            clearProps: \"transform,opacity\",\n          });\n        },\n        scope\n      );\n    },\n    { scope, dependencies: [duration, distance, stagger, ease, delay, staggered], revertOnUpdate: true }\n  );\n\n  return (\n    <div ref={scope} data-slot=\"rise-in\" className={className}>\n      {children}\n    </div>\n  );\n}\n\n/** Wrap each child you want to animate. Anything not wrapped stays still. */\nexport function RiseInItem({\n  children,\n  className,\n}: {\n  children: React.ReactNode;\n  className?: string;\n}) {\n  return (\n    <div data-slot=\"rise-in-item\" className={className}>\n      {children}\n    </div>\n  );\n}\n",
      "vue": "<script setup lang=\"ts\">\n/**\n * Reveals a stack of elements by lifting them into place, one after another.\n *\n * Under `prefers-reduced-motion: reduce` the children cross-fade in place with\n * no travel and no stagger.\n */\nimport { onMounted, onUnmounted, ref, watch } from \"vue\";\nimport gsap from \"gsap\";\n\nconst props = withDefaults(\n  defineProps<{\n    /** Seconds each child takes to arrive. */\n    duration?: number;\n    /** How far below its resting place each child starts, in pixels. */\n    distance?: number;\n    /** Seconds between one child starting and the next. */\n    stagger?: number;\n    /** A GSAP ease name, e.g. \"expo.out\". */\n    ease?: string;\n    /** Seconds to wait before the first child moves. */\n    delay?: number;\n    /** Reveal children one after another, or all together. */\n    staggered?: boolean;\n  }>(),\n  { duration: 0.9, distance: 24, stagger: 0.06, ease: \"expo.out\", delay: 0, staggered: true }\n);\n\nconst scope = ref<HTMLElement | null>(null);\nlet ctx: gsap.Context | undefined;\n\nconst play = () => {\n  ctx?.revert();\n  ctx = gsap.context(() => {\n    const items = gsap.utils.toArray<HTMLElement>(\"[data-slot='rise-in-item']\");\n    if (items.length === 0) return;\n\n    const mm = gsap.matchMedia();\n    mm.add(\n      {\n        motion: \"(prefers-reduced-motion: no-preference)\",\n        reduced: \"(prefers-reduced-motion: reduce)\",\n      },\n      (context) => {\n        const reduced = context.conditions?.reduced ?? false;\n        gsap.from(items, {\n          y: reduced ? 0 : props.distance,\n          opacity: 0,\n          duration: reduced ? 0.2 : props.duration,\n          delay: props.delay,\n          ease: reduced ? \"none\" : props.ease,\n          stagger: reduced || !props.staggered ? 0 : props.stagger,\n          clearProps: \"transform,opacity\",\n        });\n      },\n      scope.value ?? undefined\n    );\n  }, scope.value ?? undefined);\n};\n\nonMounted(play);\nwatch(() => ({ ...props }), play, { deep: true });\nonUnmounted(() => ctx?.revert());\n</script>\n\n<template>\n  <div ref=\"scope\" data-slot=\"rise-in\">\n    <slot />\n  </div>\n</template>\n",
      "html": "<!--\n  Rise In — lifts a stack of elements into place, one after another.\n  Wrap each element you want to animate in [data-slot=\"rise-in-item\"].\n  Under prefers-reduced-motion: reduce the children cross-fade with no travel.\n-->\n<div data-slot=\"rise-in\" id=\"rise-in\">\n  <div data-slot=\"rise-in-item\">Ìjẹ̀bú dark roast</div>\n  <div data-slot=\"rise-in-item\">₦7,200 a bag</div>\n  <div data-slot=\"rise-in-item\">Roasted in Yaba, Tuesdays</div>\n</div>\n\n<script type=\"module\">\n  import gsap from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/index.js\";\n\n  const scope = document.querySelector(\"#rise-in\");\n  const options = { duration: 0.9, distance: 24, stagger: 0.06, ease: \"expo.out\", delay: 0, staggered: true };\n\n  const ctx = gsap.context(() => {\n    const items = gsap.utils.toArray(\"[data-slot='rise-in-item']\");\n    if (items.length === 0) return;\n\n    gsap.matchMedia().add(\n      {\n        motion: \"(prefers-reduced-motion: no-preference)\",\n        reduced: \"(prefers-reduced-motion: reduce)\",\n      },\n      (context) => {\n        const reduced = context.conditions.reduced;\n        gsap.from(items, {\n          y: reduced ? 0 : options.distance,\n          opacity: 0,\n          duration: reduced ? 0.2 : options.duration,\n          delay: options.delay,\n          ease: reduced ? \"none\" : options.ease,\n          stagger: reduced || !options.staggered ? 0 : options.stagger,\n          clearProps: \"transform,opacity\",\n        });\n      },\n      scope\n    );\n  }, scope);\n\n  // Call ctx.revert() if you tear the section down (e.g. in a single-page app).\n</script>\n"
