      "react": "\"use client\";\n\nimport { useRef } from \"react\";\nimport gsap from \"gsap\";\nimport { ScrambleTextPlugin } from \"gsap/ScrambleTextPlugin\";\nimport { useGSAP } from \"@gsap/react\";\n\ngsap.registerPlugin(useGSAP, ScrambleTextPlugin);\n\nexport type ScrambleTextProps = {\n  /** The text that settles out of the scramble. Plain text only. */\n  children: string;\n  /** Seconds from the first scrambled frame to the settled text. */\n  duration?: number;\n  /** The characters the scramble draws from. */\n  chars?: string;\n  /** Seconds of pure scramble before letters start settling. */\n  revealDelay?: number;\n  /** How often the scrambled letters change, from 0.1 (slow) to 2 (frantic). */\n  speed?: number;\n  /** Scramble again whenever the pointer enters or the element gets focus. */\n  replayOnHover?: boolean;\n  className?: string;\n};\n\nconst srOnly: React.CSSProperties = {\n  position: \"absolute\",\n  width: 1,\n  height: 1,\n  overflow: \"hidden\",\n  clip: \"rect(0 0 0 0)\",\n  whiteSpace: \"nowrap\",\n};\n\n/**\n * Shuffles a line of text through random characters until it settles on the real words.\n *\n * Assistive tech only ever hears the real text. Under `prefers-reduced-motion: reduce`\n * the text fades in instead of scrambling.\n */\nexport function ScrambleText({\n  children,\n  duration = 1.2,\n  chars = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\",\n  revealDelay = 0.3,\n  speed = 0.6,\n  replayOnHover = false,\n  className,\n}: ScrambleTextProps) {\n  const scope = useRef<HTMLSpanElement>(null);\n  const visual = useRef<HTMLSpanElement>(null);\n\n  const { contextSafe } = useGSAP(\n    () => {\n      const el = visual.current;\n      if (!el) return;\n      gsap.matchMedia().add(\n        {\n          motion: \"(prefers-reduced-motion: no-preference)\",\n          reduced: \"(prefers-reduced-motion: reduce)\",\n        },\n        (context) => {\n          if (context.conditions?.reduced) {\n            gsap.from(el, { opacity: 0, duration: 0.2, clearProps: \"opacity\" });\n            return;\n          }\n          gsap.to(el, {\n            duration,\n            scrambleText: { text: children, chars, revealDelay, speed, tweenLength: false },\n          });\n        },\n        scope,\n      );\n    },\n    { scope, dependencies: [children, duration, chars, revealDelay, speed], revertOnUpdate: true },\n  );\n\n  const replay = contextSafe(() => {\n    const el = visual.current;\n    if (!el || !replayOnHover || gsap.isTweening(el)) return;\n    if (window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n    gsap.to(el, {\n      duration,\n      scrambleText: { text: children, chars, revealDelay, speed, tweenLength: false },\n    });\n  });\n\n  return (\n    <span\n      ref={scope}\n      data-slot=\"scramble-text\"\n      className={className}\n      style={{ position: \"relative\", display: \"inline-block\" }}\n      onPointerEnter={replay}\n      onFocus={replay}\n    >\n      <span style={srOnly}>{children}</span>\n      <span ref={visual} data-slot=\"scramble-text-visual\" aria-hidden=\"true\">\n        {children}\n      </span>\n    </span>\n  );\n}\n",
      "vue": "<script setup lang=\"ts\">\n/**\n * Shuffles a line of text through random characters until it settles on the real words.\n * Put plain text in the default slot. Assistive tech only ever hears the real text.\n * Under `prefers-reduced-motion: reduce` the text fades in instead.\n */\nimport { onMounted, onUnmounted, ref, watch } from \"vue\";\nimport gsap from \"gsap\";\nimport { ScrambleTextPlugin } from \"gsap/ScrambleTextPlugin\";\n\ngsap.registerPlugin(ScrambleTextPlugin);\n\nconst props = withDefaults(\n  defineProps<{\n    duration?: number;\n    chars?: string;\n    revealDelay?: number;\n    speed?: number;\n    replayOnHover?: boolean;\n  }>(),\n  { duration: 1.2, chars: \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\", revealDelay: 0.3, speed: 0.6, replayOnHover: false }\n);\n\nconst visual = ref<HTMLElement | null>(null);\nlet ctx: gsap.Context | undefined;\nlet text = \"\";\n\nconst scramble = () =>\n  gsap.to(visual.value, {\n    duration: props.duration,\n    scrambleText: {\n      text,\n      chars: props.chars,\n      revealDelay: props.revealDelay,\n      speed: props.speed,\n      tweenLength: false,\n    },\n  });\n\nconst play = () => {\n  ctx?.revert();\n  const el = visual.value;\n  if (!el) return;\n  // Read the real text once, before any scramble has touched it.\n  text ||= (el.textContent ?? \"\").trim();\n  ctx = gsap.context(() => {\n    gsap.matchMedia().add(\n      {\n        motion: \"(prefers-reduced-motion: no-preference)\",\n        reduced: \"(prefers-reduced-motion: reduce)\",\n      },\n      (context) => {\n        if (context.conditions?.reduced) {\n          gsap.from(el, { opacity: 0, duration: 0.2, clearProps: \"opacity\" });\n          return;\n        }\n        scramble();\n      }\n    );\n  }, el);\n};\n\nconst replay = () => {\n  const el = visual.value;\n  if (!el || !props.replayOnHover || gsap.isTweening(el)) return;\n  if (window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n  ctx?.add(scramble);\n};\n\nonMounted(play);\nwatch(() => ({ ...props }), play, { deep: true });\nonUnmounted(() => ctx?.revert());\n</script>\n\n<template>\n  <span data-slot=\"scramble-text\" class=\"scramble-text\" @pointerenter=\"replay\" @focus=\"replay\">\n    <span class=\"sr-only\"><slot /></span>\n    <span ref=\"visual\" data-slot=\"scramble-text-visual\" aria-hidden=\"true\"><slot /></span>\n  </span>\n</template>\n\n<style scoped>\n.scramble-text {\n  position: relative;\n  display: inline-block;\n}\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n}\n</style>\n",
      "html": "<!--\n  Scramble Text — shuffles a line through random characters until it settles on the real words.\n  Under prefers-reduced-motion: reduce the text fades in instead.\n-->\n<style>\n  [data-slot=\"scramble-text\"] { position: relative; display: inline-block; }\n  [data-slot=\"scramble-text\"] .sr-only {\n    position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;\n  }\n</style>\n\n<span data-slot=\"scramble-text\" id=\"scramble-text\">\n  <span class=\"sr-only\">ORDER BC-2047 CONFIRMED</span>\n  <span data-slot=\"scramble-text-visual\" aria-hidden=\"true\">ORDER BC-2047 CONFIRMED</span>\n</span>\n\n<script type=\"module\">\n  import gsap from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/index.js\";\n  import { ScrambleTextPlugin } from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/ScrambleTextPlugin.js\";\n\n  gsap.registerPlugin(ScrambleTextPlugin);\n\n  const root = document.querySelector(\"#scramble-text\");\n  const el = root.querySelector(\"[data-slot='scramble-text-visual']\");\n  const text = el.textContent.trim();\n  const options = {\n    duration: 1.2,\n    chars: \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\",\n    revealDelay: 0.3,\n    speed: 0.6,\n    replayOnHover: false,\n  };\n\n  const scramble = () =>\n    gsap.to(el, {\n      duration: options.duration,\n      scrambleText: { text, chars: options.chars, revealDelay: options.revealDelay, speed: options.speed, tweenLength: false },\n    });\n\n  const reduced = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  if (reduced) gsap.from(el, { opacity: 0, duration: 0.2, clearProps: \"opacity\" });\n  else scramble();\n\n  const replay = () => {\n    if (options.replayOnHover && !reduced && !gsap.isTweening(el)) scramble();\n  };\n  root.addEventListener(\"pointerenter\", replay);\n  root.addEventListener(\"focusin\", replay);\n</script>\n"
