    "source": {
      "react": "\"use client\";\n\nimport { useRef } from \"react\";\nimport gsap from \"gsap\";\nimport { ScrollTrigger } from \"gsap/ScrollTrigger\";\nimport { useGSAP } from \"@gsap/react\";\n\ngsap.registerPlugin(useGSAP, ScrollTrigger);\n\nexport type ScrollRevealProps = {\n  /** The elements to reveal, each wrapped in ScrollRevealItem. */\n  children: React.ReactNode;\n  /** Seconds each item takes to arrive. */\n  duration?: number;\n  /** How far below its resting place each item starts, in pixels. */\n  distance?: number;\n  /** Seconds between items that enter the viewport together. */\n  stagger?: number;\n  /** A GSAP ease name, e.g. \"power3.out\". */\n  ease?: string;\n  /** Where an item's top must reach in the viewport before it reveals, e.g. \"top 85%\". */\n  start?: string;\n  /** Reveal once and stay, or hide again when scrolled back above. */\n  once?: boolean;\n  /**\n   * The element that scrolls, if it isn't the page. Pass the element itself (from a\n   * callback ref or useState). While it is `null` nothing is set up; leave it out to\n   * use the page.\n   */\n  scroller?: HTMLElement | null;\n  className?: string;\n};\n\n/**\n * Reveals items as they scroll into view, in small staggered groups.\n *\n * Items that enter together are batched into one staggered reveal, so a fast\n * scroll down a long list doesn't queue up a slow parade. Under\n * `prefers-reduced-motion: reduce` every item is simply visible.\n */\nexport function ScrollReveal({\n  children,\n  duration = 0.7,\n  distance = 32,\n  stagger = 0.08,\n  ease = \"power3.out\",\n  start = \"top 85%\",\n  once = true,\n  scroller,\n  className,\n}: ScrollRevealProps) {\n  const scope = useRef<HTMLDivElement>(null);\n\n  useGSAP(\n    () => {\n      // A scroller was asked for but isn't mounted yet: wait for it.\n      if (scroller === null) return;\n      const items = gsap.utils.toArray<HTMLElement>(\"[data-slot='scroll-reveal-item']\");\n      if (items.length === 0) return;\n\n      gsap.matchMedia().add(\n        \"(prefers-reduced-motion: no-preference)\",\n        () => {\n          gsap.set(items, { opacity: 0, y: distance });\n          const show = (batch: Element[]) =>\n            gsap.to(batch, { opacity: 1, y: 0, duration, ease, stagger, overwrite: true });\n          const hide = (batch: Element[]) =>\n            gsap.to(batch, { opacity: 0, y: distance, duration: duration / 2, overwrite: true });\n\n          ScrollTrigger.batch(items, {\n            scroller: scroller ?? undefined,\n            start,\n            once,\n            onEnter: show,\n            onLeaveBack: once ? undefined : hide,\n          });\n        },\n        scope,\n      );\n    },\n    {\n      scope,\n      dependencies: [duration, distance, stagger, ease, start, once, scroller],\n      revertOnUpdate: true,\n    },\n  );\n\n  return (\n    <div ref={scope} data-slot=\"scroll-reveal\" className={className}>\n      {children}\n    </div>\n  );\n}\n\n/** Wrap each element you want revealed. Anything not wrapped stays put. */\nexport function ScrollRevealItem({\n  children,\n  className,\n}: {\n  children: React.ReactNode;\n  className?: string;\n}) {\n  return (\n    <div data-slot=\"scroll-reveal-item\" className={className}>\n      {children}\n    </div>\n  );\n}\n",
      "vue": "<script setup lang=\"ts\">\n/**\n * Reveals items as they scroll into view, in small staggered groups.\n * Put each item in an element with data-slot=\"scroll-reveal-item\".\n * Under `prefers-reduced-motion: reduce` every item is simply visible.\n */\nimport { onMounted, onUnmounted, ref, watch } from \"vue\";\nimport gsap from \"gsap\";\nimport { ScrollTrigger } from \"gsap/ScrollTrigger\";\n\ngsap.registerPlugin(ScrollTrigger);\n\nconst props = withDefaults(\n  defineProps<{\n    duration?: number;\n    distance?: number;\n    stagger?: number;\n    ease?: string;\n    start?: string;\n    once?: boolean;\n    /** The element that scrolls; leave out for the page. While it is null nothing is set up. */\n    scroller?: HTMLElement | null;\n  }>(),\n  { duration: 0.7, distance: 32, stagger: 0.08, ease: \"power3.out\", start: \"top 85%\", once: true }\n);\n\nconst scope = ref<HTMLElement | null>(null);\nlet ctx: gsap.Context | undefined;\n\nconst setup = () => {\n  ctx?.revert();\n  // A scroller was asked for but isn't mounted yet: wait for it.\n  if (props.scroller === null) return;\n  const el = scope.value;\n  if (!el) return;\n  ctx = gsap.context(() => {\n    const items = gsap.utils.toArray<HTMLElement>(\"[data-slot='scroll-reveal-item']\");\n    if (items.length === 0) return;\n    gsap.matchMedia().add(\"(prefers-reduced-motion: no-preference)\", () => {\n      gsap.set(items, { opacity: 0, y: props.distance });\n      ScrollTrigger.batch(items, {\n        scroller: props.scroller ?? undefined,\n        start: props.start,\n        once: props.once,\n        onEnter: (batch) =>\n          gsap.to(batch, {\n            opacity: 1,\n            y: 0,\n            duration: props.duration,\n            ease: props.ease,\n            stagger: props.stagger,\n            overwrite: true,\n          }),\n        onLeaveBack: props.once\n          ? undefined\n          : (batch) => gsap.to(batch, { opacity: 0, y: props.distance, duration: props.duration / 2, overwrite: true }),\n      });\n    });\n  }, el);\n};\n\nonMounted(setup);\nwatch(() => ({ ...props }), setup, { deep: true });\nonUnmounted(() => ctx?.revert());\n</script>\n\n<template>\n  <div ref=\"scope\" data-slot=\"scroll-reveal\">\n    <slot />\n  </div>\n</template>\n",
      "html": "<!--\n  Scroll Reveal Stagger — reveals items as they scroll into view, in small staggered groups.\n  Under prefers-reduced-motion: reduce every item is simply visible.\n-->\n<div data-slot=\"scroll-reveal\" id=\"scroll-reveal\">\n  <div data-slot=\"scroll-reveal-item\">Ìjẹ̀bú dark roast · ₦7,200</div>\n  <div data-slot=\"scroll-reveal-item\">Ọ̀yọ́ medium roast · ₦6,800</div>\n  <div data-slot=\"scroll-reveal-item\">Èkó espresso blend · ₦7,500</div>\n</div>\n\n<script type=\"module\">\n  import gsap from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/index.js\";\n  import { ScrollTrigger } from \"https://cdn.jsdelivr.net/npm/gsap@3.13.0/ScrollTrigger.js\";\n\n  gsap.registerPlugin(ScrollTrigger);\n\n  const scope = document.querySelector(\"#scroll-reveal\");\n  const options = { duration: 0.7, distance: 32, stagger: 0.08, ease: \"power3.out\", start: \"top 85%\", once: true };\n\n  const ctx = gsap.context(() => {\n    const items = gsap.utils.toArray(\"[data-slot='scroll-reveal-item']\");\n    if (items.length === 0) return;\n    gsap.matchMedia().add(\"(prefers-reduced-motion: no-preference)\", () => {\n      gsap.set(items, { opacity: 0, y: options.distance });\n      ScrollTrigger.batch(items, {\n        start: options.start,\n        once: options.once,\n        onEnter: (batch) =>\n          gsap.to(batch, { opacity: 1, y: 0, duration: options.duration, ease: options.ease, stagger: options.stagger, overwrite: true }),\n        onLeaveBack: options.once\n          ? undefined\n          : (batch) => gsap.to(batch, { opacity: 0, y: options.distance, duration: options.duration / 2, overwrite: true }),\n      });\n    });\n  }, scope);\n</script>\n"
    }
